      cctv: [
        { id: 'B.c1', type: 'write', prompt: 'Write in Korean: “I think this movie will be interesting.”', ans: ['이 영화 재미있을 것 같아요.'], soft: [{ p: '이 영화(는|가|) (재미있을|재밌을) 것 같아요', note: 'Accepted.' }], skill: 'l9.tense', diag: [{ p: '이 영화(는|가|) 재미있는 것 같아요', note: '재미있는 = it is fun (now, while watching). You haven’t seen it: 재미있을.' }, { p: '이 영화(는|가|) 재미있은 것 같아요', note: 'Future of 재미있다: 재미있을.' }], explain: 'Textbook sample sentence.', en: 'I think this movie will be interesting.' },
        { id: 'B.c2', type: 'mc', prompt: 'Sua is at her desk with books open. “I think she is studying.”', opts: ['공부하는 것 같아요', '공부한 것 같아요', '공부할 것 같아요', '공부했 것 같아요'], skill: 'l9.tense', explain: 'Now, action verb: 공부하 + 는 (WB 11).', en: 'I think she is studying.' },
        { id: 'B.c3', type: 'write', prompt: 'Write in Korean: “This place looks expensive.”', ans: ['여기 비싼 것 같아요.'], soft: [{ p: '여기(는|가|) 비싼 것 같아요', note: 'Accepted.' }], skill: 'l9.form', diag: [{ p: '여기(는|) 비싸는 것 같아요', note: 'Descriptive verb: 비싸 + ㄴ → 비싼.' }], explain: 'Textbook sample sentence.', en: 'I think this place is expensive.' },
        { id: 'B.c4', type: 'write', prompt: 'Write in Korean: “I think I probably won’t do it.”', ans: ['아마 안 할 것 같아요.'], skill: 'l9.tense', diag: [{ p: '아마 안 하는 것 같아요', note: '안 하는 = I don’t do it (now). Future: 안 할.' }, { p: '아마 안 한 것 같아요', note: '안 한 = I didn’t do it. Future: 안 할.' }], explain: 'Textbook sample sentence.', en: 'I think I probably won’t do it.' },
        { id: 'B.c5', type: 'mc', prompt: 'Everyone outside has an open umbrella. “I think it is raining.”', ko: '비가 ___ 것 같아요.', opts: ['오는', '온', '와는', '오은'], skill: 'l9.tense', explain: 'Right now, action verb: 오 + 는.', en: 'I think it is raining.' },
        { id: 'B.c6', type: 'enOpts', prompt: 'Why say 먹은 것 같아요 instead of 먹었어요?', opts: ['You are not sure: “I think he ate it” is softer.', 'It is a stronger past tense.', 'It is the future tense.', 'It is ruder.'], skill: 'l9.usage', explain: 'Textbook: -것 같아요 can mean “I think” and is used very often.', en: '' },
      ],
