MM.mnemo[9] = {"cards":[{"id":"ko-k3-0187","w":"예쁘다","cs":"hezký; pěkný; krásný","en":"to be pretty","p":"a","o":"k","ex":"이 청바지 예뻐요?","exc":"Jsou tyhle džíny hezké?","h":"JEP-PŮ ≈ „JÉ, PŮVABNÉ!“: to je hezké. 예뻐요!","m":"Nepravidelné časování ㅡ → 예뻐요. Používá se hlavně pro ženy, děti, zvířata nebo věci (pro muže spíše 잘생기다).","tv":["예뻐요","예쁠"]},{"id":"ko-k3-0188","w":"말하다","cs":"mluvit; říkat; povídat","en":"to talk, to speak","p":"v","o":"k","ex":"말한 것 같아요.","exc":"Myslím, že to řekl. (-ㄴ 것 같다 → zdá se, že)","h":"MAL ≈ MALUJE: kdo pěkně mluví, maluje slovy. 말 = řeč.","m":"Základ 말 (slovo, řeč) + 하다 (dělat) = mluvit, říkat. V minulém příčestí vzoru -ㄴ 것 같다 dává tvar 말한.","tv":["말해요","말한","말할"]},{"id":"ko-k3-0189","w":"이상하다","cs":"divný; zvláštní","en":"to be strange","p":"a","o":"s","ex":"이상한 것 같아요.","exc":"Zdá se mi to divné. (-ㄴ 것 같다 → zdá se, že)","h":"I-SANG ≈ „Í, SANGRIA?“: sangria s okurkou – to je divné.","m":"異 jiný, odlišný + 常 obvyklý = jiný než obvykle, tedy divný nebo zvláštní.","r":["i-異","sang-常"],"tv":["이상해요","이상할"]},{"id":"ko-k3-0190","w":"이야기하다","cs":"vyprávět; povídat si; mluvit","en":"to tell","p":"v","o":"k","ex":"이야기하는 것 같아요.","exc":"Zdá se, že si povídají. (-는 것 같다 → zdá se, že)","h":"이야기 (I JÁ s KYTAROU vyprávím) + 하다 = vyprávět, povídat si.","m":"Základ 이야기 (příběh, rozhovor) + 하다 (dělat) = vyprávět nebo si povídat. V hovoru se často zkracuje na 얘기하다.","tv":["이야기해요","이야기한","이야기할"]},{"id":"ko-k3-0191","w":"그렇다","cs":"takový","en":"to be so","p":"a","o":"k","ex":"그런 것 같아요.","exc":"Zdá se, že je to tak. (-ㄴ 것 같다 → zdá se, že)","h":"KŮ-RO-TA ≈ KUROPTA: „Je to taková kuropta.“ 그래요? = Opravdu? Takhle?","m":"Nepravidelné časování ㅎ → 그래요 (‚ano, je to tak‘). Před podstatným jménem má tvar 그런 (takový), jako ve výrazu 그런 것 같아요.","tv":["그래요","그럴"],"irr":"ㅎ"},{"id":"ko-k3-0192","w":"재미없다","cs":"nudný; nezáživný","en":"to be boring, not fun","p":"a","o":"k","ex":"그 영화 별로 재미없을 것 같아요.","exc":"Myslím, že ten film nebude moc zábavný. (별로 → nijak zvlášť; -을 것 같다 → asi bude)","h":"재미 = zábava (DŽE-MI ≈ DŽEM I zábava) + 없다 = není → nudný. Opak 재미있다.","m":"Složené z 재미 (zábava, zajímavost) + 없다 (nemít, neexistovat). Opak 재미있다 (zábavný, zajímavý).","tv":["재미없어요","재미없을"]},{"id":"ko-k3-0194","w":"연습하다","cs":"cvičit; trénovat; procvičovat","en":"to practice","p":"v","o":"s","ex":"연습할 것 같아요.","exc":"Myslím, že bude cvičit. (-ㄹ 것 같다 → asi bude)","h":"JON-SUP ≈ JONÁŠ SUPÍ: Jonáš trénuje, až supí.","m":"練 cvičit, trénovat + 習 cvičit, učit se = procvičovat, trénovat. 習 jako v 복습 (opakování) nebo 예습 (příprava na hodinu).","r":["yeon-練","seup-習"],"tv":["연습해요","연습한","연습할"]},{"id":"ko-k3-0195","w":"모르다","cs":"nevědět; neznat","en":"to not know","p":"v","o":"k","ex":"혜미 씨는 아직 모르는 것 같아요.","exc":"Zdá se, že to Hjemi ještě neví. (는 → téma; -는 것 같다 → zdá se, že)","h":"MO-RŮ ≈ MOR: „Mor aby to vzal, nevím!“ 몰라요 = nevím.","m":"Nepravidelné časování 르 → 몰라요 (nevím). Opak 알다 (vědět, znát).","tv":["몰라요","모른","모를"],"irr":"르"},{"id":"ko-k3-0196","w":"괜찮다","cs":"v pořádku; dobrý; nevadit","en":"to be okay","p":"a","o":"k","ex":"그것도 괜찮을 것 같아요.","exc":"Myslím, že i to bude v pořádku. (도 → také, i; -을 것 같다 → asi bude)","h":"KWEN-ČAN ≈ KVĚTINÁČ: spadl květináč, ale je v pořádku.","m":"Výslovnost [괜찬타]. V přítomném čase má tvar 괜찮아요 (‚to je v pořádku / nevadí‘).","tv":["괜찮아요","괜찮을"]},{"id":"ko-k3-0197","w":"멀다","cs":"daleký; vzdálený","en":"to be far","p":"a","o":"k","ex":"다음 집이 여기에서 멀어요?","exc":"Je další dům odsud daleko? (이 → 1. pád; 에서 → od, z)","h":"MOL ≈ MOLO: molo vede daleko do moře.","m":"Nepravidelné časování ㄹ: před ㄴ, ㅂ, ㅅ vypadává ㄹ (např. 먼 곳 = daleké místo). Opak 가깝다 (blízký).","tv":["멀어요","멀"],"irr":"ㄹ (odpadá)"},{"id":"ko-k3-0198","w":"아마","cs":"asi; pravděpodobně; nejspíš","en":"probably","p":"o","o":"k","ex":"아마 안 할 것 같아요.","exc":"Asi to neudělám. (-ㄹ 것 같다 → asi, myslím, že)","h":"A-MA ≈ „A MÁMA?“: máma asi přijde.","m":"Často stojí na začátku věty a pojí se s odhadem -을 것 같다 nebo -겠- (아마 비가 올 것 같아요 = Asi bude pršet)."},{"id":"ko-k3-0199","w":"벌써","cs":"už; již","en":"already","p":"o","o":"k","ex":"벌써 집에 간 것 같아요.","exc":"Zdá se, že už šel domů. (에 → kam; -ㄴ 것 같다 → zdá se, že)","h":"POL-SO ≈ POLSKO: „Už jsme v Polsku?“","m":"Vyjadřuje ‚už‘ často s nádechem překvapení, že se něco stalo dříve, než se čekalo. Podobné 이미 (už – neutrální konstatování)."},{"id":"ko-k3-0200","w":"별로","cs":"nijak zvlášť (se záporem); nic moc","en":"not really, not much (with a negative)","p":"o","o":"m","ex":"그 영화 별로 재미없을 것 같아요.","exc":"Myslím, že ten film nebude nijak zvlášť zábavný. (-을 것 같다 → asi bude)","h":"PJOL-LO ≈ PLOCHÝ: plochý film – nic moc. Se záporem: 별로 안 좋아요.","m":"別 zvláštní + 로: se záporem „nijak zvlášť“. 별로예요 = je to nic moc.","r":["byeol-別"]},{"id":"ko-k3-0201","w":"진짜","cs":"opravdu; fakt; skutečný","en":"really","p":"o","o":"m","ex":"이 참외 진짜 맛있어요!","exc":"Tenhle žlutý meloun je fakt výborný!","h":"DŽIN-ČA ≈ DŽIN DO ČAJE: „Opravdu? Fakt džin do čaje?“","m":"眞 pravý, skutečný + přípona 짜 = opravdový, fakt. Hovorová alternativa ke spisovnějšímu 정말. Opak 가짜 (falešný).","r":["jin-眞"]},{"id":"ko-k3-0202","w":"근데","cs":"ale; jenže; mimochodem","en":"but (short for 그런데)","p":"o","o":"k","ex":"근데 좀 비쌀 것 같아요.","exc":"Ale myslím, že to bude trochu drahé. (-ㄹ 것 같다 → asi bude)","h":"KŮN-DE ≈ KŮŇ: „Ale kůň… mimochodem, kde je?“ Zkráceně z 그런데.","m":"Hovorová zkratka spojky 그런데 (ale, a mimochodem). V psaném textu se používá plný tvar 그런데."},{"id":"ko-k3-0203","w":"맞아요","cs":"přesně tak; to je pravda; souhlasím","en":"That’s right. / I think so, too.","p":"f","o":"k","ex":"여기 맛있을 것 같아요. — 맞아요.","exc":"Myslím, že tu budou mít dobré jídlo. — Přesně tak. (-을 것 같다 → asi bude)","h":"MA-DŽA ≈ MAĎAR: „Je to Maďar?“ – „Přesně tak!“","m":"Zdvořilý tvar slovesa 맞다 (mít pravdu, sedět, trefit se). Používá se pro souhlas: ‚Přesně tak / Souhlasím‘."},{"id":"ko-k3-0204","w":"눈","cs":"sníh; oko; oči","en":"snow; eyes","p":"n","o":"k","ex":"눈이 올 것 같아요.","exc":"Zdá se, že bude sněžit. (이 → 1. pád; -ㄹ 것 같다 → asi bude)","h":"NUN: sníh ti padá do očí – 눈 je obojí. Dvě ㄴ jako dvě oči.","m":"Homonymum: znamená ‚sníh‘ i ‚oko‘. Časté spojení 눈이 오다 = sněžit."},{"id":"ko-k3-0205","w":"청바지","cs":"džíny; rifle","en":"jeans","p":"n","o":"m","ex":"이 청바지 예뻐요?","exc":"Jsou tyhle džíny hezké?","h":"바지 = kalhoty (PA-DŽI ≈ PYŽAMO) + ČONG ≈ modrá: modré kalhoty = džíny.","m":"靑 modrý + 바지 kalhoty = doslova ‚modré kalhoty‘, tedy džíny.","r":["cheong-靑"]},{"id":"ko-k3-0206","w":"숙제","cs":"domácí úkol","en":"homework","p":"n","o":"s","ex":"숙제를 할 것 같아요.","exc":"Myslím, že si udělá domácí úkol. (를 → 4. pád; -ㄹ 것 같다 → asi bude)","h":"SUK-DŽE ≈ SUK: domácí úkol je tvrdý jako suk.","m":"宿 přenocovat, doma + 題 úkol, otázka = úkol na doma, tedy domácí úkol. 題 jako v 문제 (otázka, problém).","hada":1,"r":["suk-宿","je-題"]}],"gram":{"id":"ko-k3-g09","w":"-(으)ㄴ/는/(으)ㄹ 것 같아요","en":"To look like, To seem like (used with verbs)","cs":"vypadá to, že…; myslím, že…; asi… (domněnka, odhad)","vy":"Vzorec -(으)ㄴ/는/(으)ㄹ 것 같아요 se připojuje ke kmeni slovesa nebo přídavného jména a vyjadřuje zdvořilý odhad, domněnku nebo vlastní názor (‚myslím, že… / vypadá to, že…‘). Tvar se řídí časem a slovním druhem: u přídavných jmen a v minulém čase sloves se používá -(으)ㄴ 것 같아요, v přítomném čase sloves -는 것 같아요 (platí i pro 있다/없다) a v budoucím čase -(으)ㄹ 것 같아요. Podstatná jména se pojí se sponou 이다 ve tvaru -인 것 같아요.","m":"Doslova znamená ‚je to jako věc (것), která…‘. Slouží v korejštině ke zjemnění tvrzení — místo přímého ‚je to drahé‘ (비싸요) zní 비싼 것 같아요 (‚zdá se mi to drahé‘) mnohem zdvořileji a méně kategoricky.","s":[["이상한 것 같아요.","Připadá mi to divné. / Myslím, že je to divné."],["눈이 오는 것 같아요.","Vypadá to, že sněží. / Myslím, že sněží."],["눈이 올 것 같아요.","Myslím, že bude sněžit. / Vypadá to, že bude sněžit."],["이야기한 것 같아요.","Myslím, že už o tom mluvili. / Vypadá to, že si promluvili."],["이야기할 것 같아요.","Myslím, že si spolu promluví."],["이야기하는 것 같아요.","Myslím, že spolu mluví. / Vypadá to, že se baví."],["여기 비싼 것 같아요.","Myslím, že je to tady drahé. / Tady to vypadá draze."],["그런 것 같아요.","Myslím, že ano. / Vypadá to tak."],["이 영화 재미있을 것 같아요.","Myslím, že tenhle film bude zajímavý."],["이 가방, 여기에서 산 것 같아요.","Tuhle tašku jsem myslím koupil tady."],["아마 안 할 것 같아요.","Asi to neudělám. / Myslím, že to pravděpodobně neudělám."],["여기 맛있을 것 같아요. — 맞아요.","Myslím, že tady budou mít dobré jídlo. — To souhlasí."],["근데 좀 비쌀 것 같아요.","Ale myslím, že to bude trochu drahé."],["벌써 집에 간 것 같아요.","Myslím, že už šel domů."],["혜미 씨는 아직 모르는 것 같아요.","Hjemi to myslím ještě neví."],["그 사람은 요즘 바쁜 것 같아요.","Ten člověk má v poslední době asi hodně napilno."],["그것도 괜찮을 것 같아요.","Myslím, že i to bude v pořádku."],["영어 선생님인 것 같아요.","Myslím, že je to učitelka angličtiny."]]}};
Object.assign(MM.mnRoots, {"i-異":["이","異","jiný, odlišný"],"sang-常":["상","常","stálý, obvyklý"],"yeon-練":["연","練","cvičit, trénovat"],"seup-習":["습","習","cvičit, učit se"],"byeol-別":["별","別","zvláštní, jiný"],"jin-眞":["진","眞","pravý, skutečný"],"cheong-靑":["청","靑","modrý, zelený"],"suk-宿":["숙","宿","přespat, nocleh"],"je-題":["제","題","téma, otázka"]});

